fn parse_sourcemap_map_kind(s: &str) -> Result<SourcemapMapKind> {
    Ok(match s {
        "js" => SourcemapMapKind::JS,
        "jvm" => SourcemapMapKind::JVM,
        "ios" => SourcemapMapKind::IOS,
        "react" => SourcemapMapKind::REACT,
        "flutter" => SourcemapMapKind::FLUTTER,
        "elf" => SourcemapMapKind::ELF,
        "ndk" => SourcemapMapKind::NDK,
        "il2cpp" => SourcemapMapKind::IL2CPP,
        "wasm" => SourcemapMapKind::WASM,
        "portable_pdb" => SourcemapMapKind::PORTABLE_PDB,
        _ => anyhow::bail!("invalid value {s:?}, valid values: js, jvm, ios, react, flutter, elf, ndk, il2cpp, wasm, portable_pdb"),
    })
}

fn parse_sourcemap_search_by(s: &str) -> Result<SourcemapSearchBy> {
    Ok(match s {
        "debug_id" => SourcemapSearchBy::DEBUG_ID,
        _ => anyhow::bail!("invalid value {s:?}, valid values: debug_id"),
    })
}

fn parse_sourcemap_symbol_type(s: &str) -> Result<SourcemapSymbolType> {
    Ok(match s {
        "dwarf" => SourcemapSymbolType::DWARF,
        "sourcemap" => SourcemapSymbolType::SOURCEMAP,
        _ => anyhow::bail!("invalid value {s:?}, valid values: dwarf, sourcemap"),
    })
}

